def get_model_settings(model: str, dataset: str):
    if model == "mapanything":
        return {
            "model": "mapanything",
            "model.pretrained": "\\${root_experiments_dir}/mapanything/training/mapa_v1_1/checkpoint-last.pth",
            "evaluation_resolution": "\\${dataset.resolution_options.518_1_33_ar}"
            if dataset != "kitti"
            else "\\${dataset.resolution_options.518_3_20_ar}",
        }
    elif model == "moge_1":
        return {
            "model": "moge_1",
            "evaluation_resolution": "\"'(640, 480)'\""
            if dataset != "kitti"
            else "\"'(1248,384)'\"",
        }
    elif model == "moge_2":
        return {
            "model": "moge_2",
            "evaluation_resolution": "\"'(640, 480)'\""
            if dataset != "kitti"
            else "\"'(1248,384)'\"",
        }
    elif model == "vggt":
        return {
            "model": "vggt",
            "evaluation_resolution": (
                "\\${dataset.resolution_options.518_1_33_ar}"
                if dataset != "kitti"
                else "\\${dataset.resolution_options.518_3_20_ar}"
            ),
        }
    elif model == "vggt_omega":
        return {
            "model": "vggt_omega",
            "evaluation_resolution": (
                "\\${dataset.resolution_options.512_1_33_ar}"
                if dataset != "kitti"
                else "\\${dataset.resolution_options.512_3_20_ar}"
            ),
        }
    elif model == "must3r":
        return {
            "model": "must3r",
            "evaluation_resolution": "\\${dataset.resolution_options.512_1_33_ar}"
            if dataset != "kitti"
            else "\\${dataset.resolution_options.512_3_20_ar}",
        }
    else:
        raise ValueError(f"Unknown model: {model}")
